<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;
use App\Models\Expense;
use App\Services\ImageOptimizer;
use Illuminate\Http\Request;
class ExpenseController extends Controller { public function index(){return view('admin.expenses.index',['expenses'=>Expense::latest('spent_at')->paginate(25)]);} public function create(){return view('admin.expenses.form',['expense'=>new Expense]);} private function valid(Request $r): array{return $r->validate(['category'=>'required|in:food,medical,utilities,transport,maintenance,other','title'=>'required|string|max:160','description'=>'nullable|string|max:3000','amount'=>'required|numeric|min:1|max:999999999999','spent_at'=>'required|date|before_or_equal:today','receipt'=>'nullable|image|mimes:jpg,jpeg,png,webp|max:5120','is_published'=>'nullable|boolean']);} public function store(Request $r,ImageOptimizer $images){$data=$this->valid($r);$data['is_published']=$r->boolean('is_published');$data['created_by']=$r->user()->id;if($r->hasFile('receipt'))$data['receipt_path']=$images->store($r->file('receipt'),'expense-receipts');unset($data['receipt']);Expense::create($data);return redirect()->route('admin.expenses.index')->with('success','အသုံးစရိတ် ထည့်ပြီးပါပြီ။');} public function edit(Expense $expense){return view('admin.expenses.form',compact('expense'));} public function update(Request $r,Expense $expense,ImageOptimizer $images){$data=$this->valid($r);$data['is_published']=$r->boolean('is_published');if($r->hasFile('receipt')){$images->delete($expense->receipt_path);$data['receipt_path']=$images->store($r->file('receipt'),'expense-receipts');}unset($data['receipt']);$expense->update($data);return redirect()->route('admin.expenses.index')->with('success','ပြင်ဆင်ပြီးပါပြီ။');} public function destroy(Expense $expense,ImageOptimizer $images){$images->delete($expense->receipt_path);$expense->delete();return back()->with('success','ဖျက်ပြီးပါပြီ။');} }
